// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address a, address b) public {
        vm.assume(a != b);
        vm.assume(a != address(0) && b != address(0));

        // _contractOwner is uninitialized, i.e. address(0) — the legitimate owner.
        vm.prank(address(0));
        c.setApprovedLogger(a, true);
        vm.prank(address(0));
        c.setApprovedLogger(b, false);

        assertTrue(c.approvedToLog(a) != c.approvedToLog(b));
    }
}
